// test/dual-profile.test.js — dual-profile tests

const fs = require('fs');
const path = require('path');
const os = require('os');

const root = path.join(__dirname, '..');
const { spawnHook, expectExit, hostEnv } = require('./helpers/spawned-hook');

const skillPath = path.join(root, 'src', 'SKILL.md');

// Generated bytes come from the in-memory generator output: another suite
// rewriting adapters/ on disk used to leave these reads in a truncate window
// (#66), and the committed bytes are --check's job.
const generated = require('../scripts/build-adapters').buildAdapters();

// A fresh config dir per test (#84 / #86 A): a file-wide TMP let two
// overlapping runs overwrite each other's profile and evidence mid-assertion.
let tempDirs;
beforeEach(() => { tempDirs = []; });
afterEach(() => {
  for (const dir of tempDirs) {
    try { fs.rmSync(dir, { recursive: true, force: true }); } catch (e) { /* best effort */ }
  }
});

function freshDir() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jiahao-dual-profile-test-'));
  tempDirs.push(dir);
  return dir;
}

test('SKILL.md has both profile sections', () => {
  const content = fs.readFileSync(skillPath, 'utf8');
  expect(content).toContain('## Generator Profile');
  expect(content).toContain('## Verifier Profile');
  expect(content).toContain('## Boundaries');
});

test('generator profile does NOT contain verifier-only terms', () => {
  const content = fs.readFileSync(skillPath, 'utf8');
  const genIdx = content.indexOf('## Generator Profile');
  const verIdx = content.indexOf('## Verifier Profile');
  const bndIdx = content.indexOf('## Boundaries');
  if (genIdx === -1 || verIdx === -1 || bndIdx === -1) return;
  const genSection = content.substring(genIdx, verIdx);
  expect(genSection).not.toContain('verification ladder');
  expect(genSection).not.toContain('second-party verifier');
  expect(genSection).not.toContain('The judge cannot be the author');
  expect(genSection).not.toContain('LLM critic');
});

test('verifier profile contains all required terms', () => {
  const content = fs.readFileSync(skillPath, 'utf8');
  const verIdx = content.indexOf('## Verifier Profile');
  const bndIdx = content.indexOf('## Boundaries');
  if (verIdx === -1 || bndIdx === -1) return;
  const verSection = content.substring(verIdx, bndIdx);
  expect(verSection).toContain('verification ladder');
  expect(verSection).toContain('The judge cannot be the author');
  expect(verSection).toContain('NOT VERIFIED');
  expect(verSection).toContain('anti-false-completion');
});

test('the codebuddy generator rule has surface signal rules', () => {
  const genRule = generated['adapters/codebuddy/rules/jiahao-generator.md'];
  expect(genRule).toContain('No evidence, no completion claim');
  expect(genRule).toContain('state changes');
  expect(genRule).toContain('calling a tool');
  expect(genRule).toContain('## Boundaries');
});

test('the codebuddy generator rule does NOT contain verifier tools', () => {
  const genRule = generated['adapters/codebuddy/rules/jiahao-generator.md'];
  const verdictWords = ['verification ladder', 'second-party verifier',
    'The judge cannot be the author', 'hash chain', 'confidence calibration',
    'independent LLM critic'];
  verdictWords.forEach(w => expect(genRule).not.toContain(w));
});

test('build-adapters emits both codebuddy rules and the rules-version skill', () => {
  for (const rel of [
    'adapters/codebuddy/rules/jiahao-generator.md',
    'adapters/codebuddy/rules/jiahao-verifier.md',
    'skills/jiahao/SKILL.md',
  ]) {
    expect(typeof generated[rel]).toBe('string');
    expect(fs.existsSync(path.join(root, rel))).toBe(true);
  }
  for (const retired of require('../scripts/build-adapters').RETIRED_HOSTS) {
    expect(fs.existsSync(path.join(root, 'adapters', retired))).toBe(false);
  }
});

test('activate hook uses generator profile when flag set', () => {
  const dir = freshDir();
  fs.writeFileSync(path.join(dir, '.jiahao-profile'), 'generator', 'utf8');
  fs.writeFileSync(path.join(dir, '.jiahao-active'), 'full', 'utf8');
  const res = spawnHook(path.join(root, 'hooks', 'jiahao-activate.js'), {
    env: hostEnv(dir), cwd: root,
  });
  expectExit(res, 0);
  // Generator profile should NOT contain verification ladder content
  expect(res.stdout).not.toContain('deterministic machine check');
  expect(res.stdout).not.toContain('second-party verifier');
  // Should contain generator rules
  expect(res.stdout).toContain('No evidence, no completion claim');
});

test('verdict-gate advisory mode for generator profile', () => {
  const dir = freshDir();
  fs.writeFileSync(path.join(dir, '.jiahao-profile'), 'generator', 'utf8');
  fs.writeFileSync(path.join(dir, '.jiahao-active'), 'full', 'utf8');
  const res = spawnHook(path.join(root, 'hooks', 'jiahao-verdict-gate.js'), {
    stdin: JSON.stringify({ stop_hook_active: false }), env: hostEnv(dir), cwd: root,
  });
  // Generator mode: allow, not block — verify explicit advisory output
  expectExit(res, 0);
  expect(res.stdout).toContain('"decision":"allow"');
  expect(res.stdout).toContain('JIAHAO ADVISORY');
  expect(res.stdout).not.toContain('"decision":"block"');
});
